// The lock protocol is infrastructure: rolling application code back must not
// restore the stale-unlink implementation from a retained bootstrap.
import { constants } from 'node:fs';
import { createHash, randomUUID } from 'node:crypto';
import { lstat, open, readdir, rename, unlink } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { HelperError, clock, type Timing } from './config.js';
import { assertNoSymlinks, atomicWrite, ensurePrivateDirectory, inside, readPrivateFile, type HelperPaths } from './paths.js';
import { acquireWriteGuard } from './write-lock.js';
import { RELEASE_IDENTITY } from './release-identity.js';
import { captureRetirement, pendingRetirement, restartLegacyService, formatRetirementMessage, type Retirement } from './write-lock-retirement.js';

const protocol = '// maddots-write-lock-protocol: 3';
// A protocol can retain its on-disk lock ABI while its coordinator needs a
// repair. Adopt this infrastructure revision once, including from pre-fix
// protocol-3 records, and never downgrade a newer retained implementation.
// Linux revision 2 replaces the utility's numeric timeout signal with retained
// responsibility. Keep macOS on its existing coordinator revision in this slice.
const revision = process.platform === 'linux' ? 2 : 1;
const sidecar = '.write-lock-upgrade.json';
// Keep every dependency importable throughout an interrupted protocol-2
// upgrade. write-lock.js publishes the protocol marker only after its entire
// migration dependency graph is installed. paths.js is retrofitted last.
const modules = ['linux-proc.js', 'process-image.js', 'write-lock-retirement.js', 'write-lock-upgrade.js', 'write-lock.js'] as const;
const digest = (text: string) => createHash('sha256').update(text).digest('hex');
let coordinator: string | undefined;
interface UpgradeState {
  protocol: 2 | 3;
  revision?: number;
  bootstrap: string;
  data: string[];
  patching?: boolean;
  retirement?: Retirement;
  sources: Record<string, string>;
}
interface Runtime { bundledRoot: string; runningRoot: string }

async function moduleText(path: string): Promise<string> {
  await assertNoSymlinks(path);
  const file = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
  try {
    const info = await file.stat();
    if (!info.isFile() || info.uid !== process.getuid?.() || info.nlink !== 1 || (info.mode & 0o022) || info.size > 4 * 1024 * 1024) {
      throw new HelperError('FILE_UNSAFE', 'The installed helper module must be an owned, regular file that other users cannot write.');
    }
    return await file.readFile('utf8');
  } finally { await file.close(); }
}

async function replaceModule(path: string, text: string): Promise<void> {
  await assertNoSymlinks(path);
  const folder = await lstat(dirname(path));
  if (!folder.isDirectory() || folder.uid !== process.getuid?.() || (folder.mode & 0o022)) {
    throw new HelperError('PATH_UNSAFE', 'Reinstall the helper in a user-owned location before upgrading its lock implementation.');
  }
  try { await moduleText(path); } catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error; }
  const temporary = join(dirname(path), '.' + randomUUID() + '.tmp');
  const file = await open(temporary, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | constants.O_NOFOLLOW, 0o600);
  try {
    await file.writeFile(text); await file.sync(); await file.close();
    await assertNoSymlinks(path); await rename(temporary, path);
    const directory = await open(dirname(path), constants.O_RDONLY);
    try { await directory.sync(); } finally { await directory.close(); }
    if (digest(await moduleText(path)) !== digest(text)) throw new HelperError('CANDIDATE_FAILED', 'The helper lock migration could not be verified.');
  } finally { await file.close().catch(() => {}); await unlink(temporary).catch(() => {}); }
}

function retrofit(text: string): string | undefined {
  if (text.includes("export { withWriteLock } from './write-lock.js';")) return;
  // Only the known bootstrap ABI is retrofitted. Preserve all path helpers and
  // the original application version. The old function becomes unreachable
  // through module exports; all existing importers receive the guarded one.
  const declaration = /export async function withWriteLock\(paths, action, timing = clock, alive = processAlive(?:, deadline = timing\.now\(\) \+ 10_000)?\) \{/g;
  if ([...text.matchAll(declaration)].length !== 1 || text.includes('legacyWithWriteLock')) {
    throw new HelperError('CANDIDATE_FAILED', 'This bootstrap has an unsupported write-lock implementation.');
  }
  return text.replace(declaration, match => match.replace('export async function withWriteLock', 'async function legacyWithWriteLock')) +
    "\nexport { withWriteLock } from './write-lock.js';\n";
}

async function inventory(state: UpgradeState): Promise<{root: string; unpublished: boolean}[]> {
  const result = [{root: state.bootstrap, unpublished: false}];
  for (const data of state.data) {
    const updates = join(data, 'updates');
    for (const [directory, staged] of [[updates, true], [join(updates, 'releases'), false]] as const) {
      await assertNoSymlinks(directory);
      let entries;
      try { entries = await readdir(directory, {withFileTypes: true}); }
      catch (error) { if ((error as NodeJS.ErrnoException).code === 'ENOENT') continue; throw error; }
      for (const entry of entries) {
        if (!(staged ? /^staging-/.test(entry.name) : /^[a-f0-9]{40}$/.test(entry.name))) continue;
        if (!entry.isDirectory() || entry.isSymbolicLink()) continue; // The release selector rejects these too.
        result.push({root: join(directory, entry.name), unpublished: staged});
      }
    }
  }
  return result;
}

async function readState(directory: string): Promise<UpgradeState> {
  const text = await readPrivateFile(join(directory, 'state.json'));
  let state: UpgradeState;
  try { state = JSON.parse(text) as UpgradeState; }
  catch { throw new HelperError('FILE_UNSAFE', 'The helper lock migration record is invalid.'); }
  if (!state || typeof state !== 'object' || ![2, 3].includes(state.protocol) || typeof state.bootstrap !== 'string' || !Array.isArray(state.data) ||
      state.data.some(path => typeof path !== 'string' || resolve(path) !== path) || resolve(state.bootstrap) !== state.bootstrap ||
      (state.revision !== undefined && (!Number.isSafeInteger(state.revision) || state.revision < 1)) ||
      (state.patching !== undefined && state.patching !== true) ||
      (state.retirement !== undefined && (!state.retirement || typeof state.retirement !== 'object' || !/^[0-9a-f-]{36}$/.test(state.retirement.boot) || !Array.isArray(state.retirement.processes) ||
        state.retirement.processes.some(p => !p || !Number.isSafeInteger(p.pid) || p.pid <= 0 || typeof p.started !== 'string' || !p.started ||
          typeof p.executable !== 'string' || !p.executable))) ||
      !state.sources || modules.filter(name => state.protocol !== 2 || name !== 'linux-proc.js').some(name => !/^[a-f0-9]{64}$/.test(state.sources[name]))) {
    throw new HelperError('FILE_UNSAFE', 'The helper lock migration record is invalid.');
  }
  return state;
}
const saveState = (directory: string, state: UpgradeState) => atomicWrite(join(directory, 'state.json'), JSON.stringify(state) + '\n');

async function maintain(directory: string, state: UpgradeState): Promise<void> {
  const sources = new Map<string, string>();
  for (const name of modules) {
    const text = await readPrivateFile(join(directory, name), 4 * 1024 * 1024);
    if (digest(text) !== state.sources[name]) throw new HelperError('INVALID_CHECKSUM', 'The retained lock migration source changed.');
    sources.set(name, text);
  }
  for (const {root, unpublished} of await inventory(state)) {
    if (unpublished) {
      // Extraction may still be running, or may have crashed halfway through.
      // Only a validated stage can reach the updater's activation callback.
      try { await readPrivateFile(join(root, '.ready.json'), 64 * 1024); }
      catch (error) { if ((error as NodeJS.ErrnoException).code === 'ENOENT') continue; throw error; }
    }
    if (root !== state.bootstrap && !unpublished) {
      try { await moduleText(join(root, 'dist', 'cli.js')); }
      catch { continue; } // The existing selector cannot launch this release.
    }
    const target = join(root, 'dist', 'paths.js');
    let old: string, next: string | undefined;
    try {
      old = await moduleText(target); next = retrofit(old);
      if (!next) {
        let lock: string | undefined;
        try { lock = await moduleText(join(root, 'dist', 'write-lock.js')); }
        catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error; }
        if (lock !== undefined && !lock.startsWith(protocol) && !lock.startsWith('// maddots-write-lock-protocol: 2')) {
          throw new HelperError('CANDIDATE_FAILED', 'The selected runtime does not implement the guarded lock protocol.');
        }
      }
    }
    catch (error) {
      if (root === state.bootstrap) throw error;
      if (unpublished) {
        // Preserve a refused candidate outside the activation namespace. Its
        // updater cannot rename the old stage path and publish unsafe code.
        await rename(root, join(dirname(root), 'refused-stage-' + randomUUID()));
        throw new HelperError('CANDIDATE_FAILED', 'The candidate has an unsupported write-lock implementation.');
      }
      // A broken cached release must not strand bootstrap rollback. Preserve
      // its launcher outside the executable path, which also makes the legacy
      // selector reject it. Retire any already-loaded copy before admitting a
      // writer; repeated launches then skip the disabled cached release.
      state.patching = true; await saveState(directory, state);
      await rename(join(root, 'dist', 'cli.js'), join(root, 'dist', '.refused-cli-' + randomUUID() + '.js'));
      continue;
    }
    // A protocol marker proves only that one module was published. Compare
    // every retained module even after the marker appears, so old interrupted
    // migrations and later missing modules can never skip the repair barrier.
    const repairs: typeof modules[number][] = [];
    for (const name of modules) {
      let text: string | undefined;
      try { text = await moduleText(join(root, 'dist', name)); }
      catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error; }
      if (text === undefined || digest(text) !== state.sources[name]) repairs.push(name);
    }
    if (next || repairs.length) {
      // Persist the barrier BEFORE the first replacement. An interrupted
      // migration is resumable, but no partially migrated writer may enter.
      // Stages are not executable supported runtimes yet: the updater's inner
      // main lock checks their final bytes before rename and pointer activation.
      if (!unpublished) { state.patching = true; await saveState(directory, state); }
      if (next) await atomicWrite(join(directory, digest(old) + '.paths-backup.js'), old);
      await atomicWrite(join(root, 'dist', sidecar), JSON.stringify({directory}) + '\n');
      for (const name of repairs) await replaceModule(join(root, 'dist', name), sources.get(name)!);
      if (next) await replaceModule(target, next);
    } else {
      await atomicWrite(join(root, 'dist', sidecar), JSON.stringify({directory}) + '\n');
    }
  }
  if (state.patching) {
    // Capture AFTER the last replacement. Processes that imported old code
    // during the retrofit are included, as is this caller's old bootstrap.
    // If inspection or persistence fails, the on-disk patching barrier stays.
    const previous = state.retirement ? await pendingRetirement(state.retirement) : [];
    const retirement = await captureRetirement();
    if (state.retirement?.boot === retirement.boot) {
      const processes = new Map(retirement.processes.map(row => [row.pid, row]));
      // Refreshing infrastructure must not forget a saved, still-live host
      // merely because its current image is exempt from a fresh capture.
      for (const row of previous) if (!processes.has(row.pid)) processes.set(row.pid, row);
      retirement.processes = [...processes.values()].sort((a, b) => a.pid - b.pid);
    }
    state.retirement = retirement;
    delete state.patching;
    await saveState(directory, state);
  }
  if (state.retirement) {
    let pending = await pendingRetirement(state.retirement);
    if (pending.length) {
      // Only our named background service may be restarted. Its own process
      // exits with HELPER_BUSY and the service manager starts a fresh process.
      await restartLegacyService(pending);
      pending = await pendingRetirement(state.retirement);
    }
    if (pending.length) throw new HelperError('HELPER_BUSY', formatRetirementMessage(pending));
    // A legacy updater may have published one last runtime after our inventory
    // but before its process exited. With that cohort gone, inventory once more
    // before admitting any writer. A newly found legacy root starts a new barrier.
    delete state.retirement;
    await maintain(directory, state);
    await saveState(directory, state);
  }
}

/** Called by the selected CLI before any state-changing command. */
export async function prepareLockUpgrade(runtime: Runtime, paths: HelperPaths, timing: Timing = clock): Promise<void> {
  const directory = join(runtime.bundledRoot, '.write-lock-upgrade');
  try { await ensurePrivateDirectory(directory); }
  catch (error) {
    if (['EACCES', 'EPERM', 'EROFS'].includes((error as NodeJS.ErrnoException).code ?? '')) {
      throw new HelperError('PATH_UNSAFE', 'Reinstall the helper in a user-owned location before upgrading its lock implementation.');
    }
    throw error;
  }
  const unlock = await acquireWriteGuard(join(directory, '.guard'), timing, timing.now() + 10_000);
  try {
    let state: UpgradeState;
    try { state = await readState(directory); }
    catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
      const sources: Record<string, string> = {};
      for (const name of modules) {
        const text = await moduleText(fileURLToPath(new URL('./' + name, import.meta.url)));
        sources[name] = digest(text); await atomicWrite(join(directory, name), text);
      }
      // Absence alone is not evidence of an old process. Existing application
      // state or locks are evidence that npm may have replaced a loaded runtime;
      // old installed module bytes also set the barrier during maintain().
      let existing = false;
      for (const path of [paths.state, paths.lock, paths.lock + '.guard']) {
        try { await lstat(path); existing = true; }
        catch (inspection) { if ((inspection as NodeJS.ErrnoException).code !== 'ENOENT') throw inspection; }
      }
      state = {protocol: 3, revision, bootstrap: resolve(runtime.bundledRoot), data: [paths.data], sources, ...(existing ? {patching: true} : {})};
      await saveState(directory, state);
    }
    if (state.bootstrap !== resolve(runtime.bundledRoot)) throw new HelperError('PATH_UNSAFE', 'The lock migration belongs to another bootstrap.');
    if (state.protocol === 2 || (state.revision ?? 0) < revision) {
      // Retain the old record's barrier and cohort while upgrading migration
      // infrastructure. The revision also replaces pre-fix protocol-3 sources;
      // a partially copied snapshot is retried until this state save commits.
      const sources: Record<string, string> = {};
      for (const name of modules) {
        const text = await moduleText(fileURLToPath(new URL('./' + name, import.meta.url)));
        sources[name] = digest(text); await atomicWrite(join(directory, name), text);
      }
      state.sources = sources; state.protocol = 3; state.revision = revision; state.patching = true;
      await saveState(directory, state);
    }
    if (!state.data.includes(paths.data)) { state.data.push(paths.data); state.patching = true; await saveState(directory, state); }
    coordinator = directory;
    await maintain(directory, state);
  } finally { await unlock(); }
}

/** Every retrofitted bootstrap, rollback runtime and nested updater uses this. */
export async function assertLockUpgradeReady(paths: HelperPaths, timing: Timing = clock): Promise<void> {
  let directory = coordinator;
  if (!directory) {
    try {
      const value = JSON.parse(await readPrivateFile(fileURLToPath(new URL('./' + sidecar, import.meta.url))));
      if (typeof value.directory !== 'string' || resolve(value.directory) !== value.directory) throw new HelperError('FILE_UNSAFE', 'Invalid lock migration location.');
      directory = value.directory;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
      if (RELEASE_IDENTITY && fileURLToPath(import.meta.url).endsWith('.js')) throw new HelperError('HELPER_BUSY', 'Run maddots-ai status to finish the helper lock upgrade, then retry.');
      return; // Uninstalled source fixtures have no retained runtime to migrate.
    }
  }
  const unlock = await acquireWriteGuard(join(directory!, '.guard'), timing, timing.now() + 10_000);
  try {
    const state = await readState(directory!);
    // Only prepareLockUpgrade has selected an intact runtime as the source of
    // a newer coordinator revision. A guarded caller must not restore retained
    // pre-fix modules over that runtime before its source snapshot is adopted.
    if (state.protocol === 2 || (state.revision ?? 0) < revision) {
      throw new HelperError('HELPER_BUSY', 'Run maddots-ai status to finish the helper lock upgrade, then retry.');
    }
    // Old CLIs do not call prepareLockUpgrade. Their full paths still identify
    // the real data root even when the updater overrides data for its own lock.
    if (typeof paths.state === 'string') {
      // Linux puts state in XDG_STATE_HOME. The updater changes data/lock for
      // its nested lock but retains logs under the real application data root.
      const data = process.platform === 'linux' ? (typeof paths.logs === 'string' ? dirname(paths.logs) :
        state.data.find(root => inside(root, paths.data)) ?? paths.data) : dirname(paths.state);
      if (!state.data.includes(data)) { state.data.push(data); state.patching = true; await saveState(directory!, state); }
    } else if (!state.data.some(data => inside(data, paths.data))) {
      throw new HelperError('PATH_UNSAFE', 'The helper data root must be registered before acquiring a nested lock.');
    }
    await maintain(directory!, state);
  }
  finally { await unlock(); }
  // Never keep the migration guard across the caller's action: updater and
  // agent operations legitimately nest distinct application locks.
}

modules.write-lock-retirement:
// A saved cohort, rather than a timeout, retires JavaScript already in memory.
// Supported helper children use spawn/exec, so children started after all launch
// roots are patched read the new modules. Node workers retain their host PID.
import { posix } from 'node:path';
import { HelperError, runCommand, type Runner } from './config.js';
import { processImages } from './process-image.js';
import { linuxBootId, linuxProcessTable, type LinuxProcess } from './linux-proc.js';

// Persist only the boot UUID and process PID/start time for lifetime checks, plus
// the verified executable path so retry instructions identify the app to close.
// Real UID and zombie state are checked during scans, never stored in the cohort.
export interface ProcessIdentity { pid: number; started: string; executable: string }
export interface Retirement { boot: string; processes: ProcessIdentity[] }
/** Function arguments are fixture seams, never executable choices from argv/env. */
export interface RetirementOptions {
  runner?: Runner;
  uid?: number;
  pid?: number;
  platform?: NodeJS.Platform;
  images?: typeof processImages;
  linux?: {
    boot: () => Promise<string>;
    table: (options: {uid: number; exe?: boolean}) => Promise<LinuxProcess[]>;
  };
}

const BOOT = /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/iu;
const INSPECTION_MESSAGE = 'The helper could not verify which old processes are still running. Retry the command. If this continues, quit and reopen your AI tools and command terminals, then retry.';
const busy = (message = INSPECTION_MESSAGE) => new HelperError('HELPER_BUSY', message);
const ENV = { LC_ALL: 'C', TZ: 'UTC0' };
const SERVICE = 'app.maddots.ai.helper';
// The supported runtime is Node CLI processes, spawn/exec children and workers.
// Native injection, dlopen-based Node embedding and native fork-without-exec
// inheritance are outside that model; including them would invalidate even
// stock shell exemptions. Only kernel paths qualify, never ps comm/argv0.
const NO_HELPER_IMAGE = new Set([
  '/bin/bash', '/bin/csh', '/bin/dash', '/bin/ksh', '/bin/sh', '/bin/tcsh', '/bin/zsh',
  '/sbin/launchd', '/bin/launchctl', '/bin/ps', '/usr/sbin/sysctl',
  '/usr/sbin/cfprefsd', '/usr/sbin/distnoted', '/usr/sbin/notifyd', '/usr/sbin/syslogd',
  '/usr/libexec/pboard', '/usr/libexec/pbs', '/usr/libexec/lsd',
]);
const validPid = (pid: number) => Number.isSafeInteger(pid) && pid > 0;
const isControl = (value: string) => value.charCodeAt(0) < 32 || value.charCodeAt(0) === 127;
const printable = (value: string) => value.length > 0 && value.length <= 4096 && ![...value].some(isControl);
const HOST_BASENAME = /^(?:node.*|bun(?:x|[ ._-].*|\d.*)?|deno(?:[ ._-].*|\d.*)?|electron.*|osascript.*|osacompile.*|applet|python.*|ruby.*|perl.*|java.*|jsc(?:[-_.]?\d.*)?|js(?:[-_.]?\d.*)?|qjs(?:[-_.]?\d.*)?|quickjs.*|d8|v8.*|.*extension[ -]?host.*|.*helper \(plugin\).*)$/iu;

/** Classify canonical kernel images under the supported Node runtime model. */
export function isStockNonHostImage(image: string): boolean {
  if (!printable(image) || !posix.isAbsolute(image) || posix.normalize(image) !== image ||
      HOST_BASENAME.test(posix.basename(image))) return false;
  // These sealed stock roots do not host helper JS through a supported API.
  // The trailing slash is deliberate: similarly named external paths qualify
  // for no exemption. Known interpreters/extension hosts above always remain.
  return NO_HELPER_IMAGE.has(image) || image.startsWith('/System/Library/') || image.startsWith('/usr/libexec/');
}

function settings(options: RetirementOptions): {runner: Runner; uid: number; pid: number; platform: NodeJS.Platform} {
  const uid = options.uid ?? process.getuid?.(), pid = options.pid ?? process.pid;
  const platform = options.platform ?? process.platform;
  if (!['darwin', 'linux'].includes(platform) || uid === undefined ||
      !Number.isSafeInteger(uid) || uid < 0 || !validPid(pid)) throw busy();
  return { runner: options.runner ?? runCommand, uid, pid, platform };
}

const LINUX_NON_HOSTS = new Set([
  '/usr/bin/bash', '/usr/bin/dash', '/usr/bin/zsh', '/usr/bin/fish', '/usr/bin/sh',
  '/usr/bin/flock', '/usr/bin/systemctl', '/usr/bin/ps', '/usr/bin/sleep', '/usr/bin/timeout',
  '/usr/lib/systemd/systemd',
]);

async function linuxBoot(options: RetirementOptions): Promise<string> {
  try {
    const boot = await (options.linux?.boot ?? linuxBootId)();
    if (!BOOT.test(boot)) throw busy();
    return boot.toLowerCase();
  } catch { throw busy(); }
}

async function linuxRows(context: ReturnType<typeof settings>, options: RetirementOptions, exe = false): Promise<LinuxProcess[]> {
  try {
    // Retirement covers independently launched old Node CLI/module hosts too,
    // not just S3 workloads. An unreadable host outside every helper cgroup can
    // still retain old JS, so contained-run outsider exclusion is unsafe here.
    // Relaxing this needs trusted proof that the old writer generation drained.
    const rows = await (options.linux?.table ?? linuxProcessTable)({uid: context.uid, exe});
    if (!rows.some(row => row.pid === context.pid && !row.zombie) ||
        rows.some(row => row.uid !== context.uid || !validPid(row.pid) || !BOOT.test(row.bootId) ||
          !/^\d+$/u.test(row.startTicks) || row.startedAt !== `linux:${row.bootId}:${row.startTicks}`) ||
        new Set(rows.map(row => row.pid)).size !== rows.length) throw busy();
    return rows;
  } catch { throw busy(); }
}

async function captureLinux(options: RetirementOptions, context: ReturnType<typeof settings>): Promise<Retirement> {
  const boot = await linuxBoot(options), rows = await linuxRows(context, options, true);
  if (await linuxBoot(options) !== boot) return {boot, processes: []};
  const processes: ProcessIdentity[] = [];
  for (const row of rows) {
    if (row.bootId !== boot) throw busy();
    if (row.zombie) continue;
    const image = row.pid === context.pid ? process.execPath : row.exe;
    if (!image || !printable(image) || !posix.isAbsolute(image) || posix.normalize(image) !== image) throw busy();
    // Linux has no sealed system roots. Only exact known native images qualify
    // for an exemption; arbitrary programs under /usr/libexec remain candidates.
    if (row.pid === context.pid || (!NO_HELPER_IMAGE.has(image) && !LINUX_NON_HOSTS.has(image))) {
      processes.push({pid: row.pid, started: row.startedAt, executable: image});
    }
  }
  return {boot, processes: processes.sort((a, b) => a.pid - b.pid)};
}

async function bootId(runner: Runner): Promise<string> {
  try {
    const result = await runner('/usr/sbin/sysctl', ['-n', 'kern.bootsessionuuid'], {env: ENV, timeout: 2000});
    if (result.stderr.trim()) throw busy();
    const value = result.stdout.trim();
    if (!BOOT.test(value)) throw busy();
    return value.toLowerCase();
  } catch { throw busy(); }
}

const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const weekdays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
function canonicalStart(value: string): string {
  const match = /^(Sun|Mon|Tue|Wed|Thu|Fri|Sat)\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(\d{1,2})\s+(\d{2}):(\d{2}):(\d{2})\s+(\d{4})$/u.exec(value);
  if (!match) throw busy();
  const [, weekday, month, day, hour, minute, second, year] = match;
  const date = new Date(Date.UTC(Number(year), months.indexOf(month), Number(day), Number(hour), Number(minute), Number(second)));
  if (Number(year) < 1970 || date.getUTCFullYear() !== Number(year) || date.getUTCMonth() !== months.indexOf(month) ||
      date.getUTCDate() !== Number(day) || date.getUTCHours() !== Number(hour) || date.getUTCMinutes() !== Number(minute) ||
      date.getUTCSeconds() !== Number(second) || weekdays[date.getUTCDay()] !== weekday) throw busy();
  return `${weekday} ${month} ${Number(day)} ${hour}:${minute}:${second} ${year}`;
}

interface ProcessRow {pid: number; started: string; zombie: boolean}
function parseTable(stdout: string, uid: number, ownPid: number): ProcessRow[] {
  // execFile rejects maxBuffer overflow. Requiring the final newline also rejects
  // a partial final row instead of accidentally interpreting it as disappearance.
  if (!stdout || !stdout.endsWith('\n') || stdout.length > 1024 * 1024) throw busy();
  // Do not request ps comm: Darwin derives it from mutable argv0.
  const seen = new Set<number>(), rows: ProcessRow[] = [];
  for (const line of stdout.slice(0, -1).split('\n')) {
    const match = /^\s*(\d+)\s+(\d+)\s+([IRSTUZ][+<>AELNSsVWX]*)\s+((?:Sun|Mon|Tue|Wed|Thu|Fri|Sat)\s+\S+\s+\d{1,2}\s+\d{2}:\d{2}:\d{2}\s+\d{4})\s*$/u.exec(line);
    if (!match) throw busy();
    const pid = Number(match[1]), user = Number(match[2]);
    if (!validPid(pid) || user !== uid || seen.has(pid)) throw busy();
    seen.add(pid);
    rows.push({pid, zombie: match[3].startsWith('Z'), started: canonicalStart(match[4])});
  }
  if (!rows.some(row => row.pid === ownPid && !row.zombie)) throw busy();
  return rows;
}

async function processTable(context: ReturnType<typeof settings>): Promise<ProcessRow[]> {
  try {
    // A single real-UID selector restricts Darwin's kernel query (KERN_PROC_RUID),
    // including processes without a terminal. Never collect all users then filter.
    const result = await context.runner('/bin/ps', ['-U', String(context.uid), '-o', 'pid=,ruid=,state=,lstart='], {env: ENV, timeout: 2000});
    if (result.stderr.trim()) throw busy();
    return parseTable(result.stdout, context.uid, context.pid);
  } catch { throw busy(); }
}

/** Call after every supported on-disk legacy launch root is patched/disabled. */
export async function captureRetirement(options: RetirementOptions = {}): Promise<Retirement> {
  const context = settings(options);
  if (context.platform === 'linux') return captureLinux(options, context);
  const boot = await bootId(context.runner);
  const rows = await processTable(context);
  // An unreaped zombie has exited even though Darwin retains its PID/start time.
  // Its executable path may already return ESRCH, so do not request an image.
  const owned = rows.filter(row => !row.zombie);
  let images: Map<number, string>;
  try { images = await (options.images ?? processImages)(owned.filter(row => row.pid !== context.pid).map(row => row.pid), context.runner, {platform: context.platform}); }
  catch { throw busy(); }
  // Bind every image to the captured real UID, start time and boot session before
  // retaining it. The user-filtered scan omits PIDs now owned by another user;
  // its parser also rejects any unexpected UID. A replaced lifetime has exited,
  // and its replacement's image must never enter the saved cohort.
  // Exec discards loaded modules; a later exec reads the patched launch roots.
  const verified = new Map((await processTable(context)).map(row => [row.pid, row]));
  if (await bootId(context.runner) !== boot) return {boot, processes: []};
  const processes: ProcessIdentity[] = [];
  for (const row of owned) {
    const current = verified.get(row.pid);
    if (!current || current.started !== row.started || current.zombie) continue;
    if (row.pid === context.pid) { processes.push({pid: row.pid, started: row.started, executable: process.execPath}); continue; }
    const image = images.get(row.pid);
    // ESRCH alone cannot retire an identity still live in the second scan.
    if (!image || !image.startsWith('/') || !printable(image)) throw busy();
    if (!isStockNonHostImage(image)) {
      processes.push({pid: row.pid, started: row.started, executable: image});
    }
  }
  return {boot, processes: processes.sort((a, b) => a.pid - b.pid)};
}

/** A new image/title does not prove a process discarded an imported module. */
export async function pendingRetirement(retirement: Retirement, options: RetirementOptions = {}): Promise<ProcessIdentity[]> {
  const context = settings(options);
  if (!BOOT.test(retirement.boot) || !Array.isArray(retirement.processes) || retirement.processes.some(row =>
    !row || !validPid(row.pid) || typeof row.started !== 'string' ||
    (context.platform === 'linux' ? !new RegExp(`^linux:${retirement.boot.toLowerCase()}:\\d+$`, 'u').test(row.started) : canonicalStart(row.started) !== row.started) ||
    typeof row.executable !== 'string' || !printable(row.executable)) ||
    new Set(retirement.processes.map(row => row.pid)).size !== retirement.processes.length) throw busy();
  if (context.platform === 'linux') {
    if (await linuxBoot(options) !== retirement.boot.toLowerCase()) return [];
    const rows = await linuxRows(context, options);
    if (await linuxBoot(options) !== retirement.boot.toLowerCase()) return [];
    const live = new Map(rows.filter(row => !row.zombie).map(row => [row.pid, row.startedAt]));
    return retirement.processes.filter(row => live.get(row.pid) === row.started);
  }
  if (await bootId(context.runner) !== retirement.boot.toLowerCase()) return [];
  const rows = await processTable(context), live = new Map(rows.filter(row => !row.zombie).map(row => [row.pid, row.started]));
  // lstart has second precision. A PID reused in that same second remains busy,
  // which is conservative; a different start identity proves the old PID exited.
  return retirement.processes.filter(row => live.get(row.pid) === row.started);
}

function servicePid(stdout: string): number | undefined {
  if (!stdout.endsWith('\n') || stdout.length > 1024 * 1024) throw busy();
  const [header, ...lines] = stdout.slice(0, -1).split('\n');
  if (!/^PID\s+Status\s+Label$/u.test(header)) throw busy();
  const labels = new Set<string>();
  let result: number | undefined;
  for (const line of lines) {
    const match = /^(\d+|-)\s+(-?\d+|-)\s+(\S(?:.*\S)?)$/u.exec(line);
    if (!match) throw busy();
    const [, pid, status, label] = match;
    if ((pid !== '-' && !validPid(Number(pid))) || (status !== '-' && !Number.isSafeInteger(Number(status))) ||
        !printable(label) || labels.has(label)) throw busy();
    labels.add(label);
    if (label === SERVICE && pid !== '-') result = Number(pid);
  }
  return result;
}

/** Restart only our own launchd label, never a numeric PID or an AI tool. */
export async function restartLegacyService(pending: readonly ProcessIdentity[], options: RetirementOptions = {}): Promise<void> {
  const context = settings(options);
  if (!pending.some(row => row.pid !== context.pid)) return;
  if (context.platform === 'linux') {
    const unit = `${SERVICE}.service`, env = {...ENV, XDG_RUNTIME_DIR: `/run/user/${context.uid}`,
      DBUS_SESSION_BUS_ADDRESS: `unix:path=/run/user/${context.uid}/bus`};
    const message = `The helper could not restart its background service. Run systemctl --user restart ${unit}, then retry the helper command.`;
    try {
      const result = await context.runner('/usr/bin/systemctl', ['--user', 'show', unit, '--property=Id,LoadState,MainPID', '--no-pager'], {env, timeout: 2000});
      if (result.stderr.trim() || !result.stdout.endsWith('\n') || result.stdout.length > 4096) throw busy();
      const fields = new Map<string, string>();
      for (const line of result.stdout.slice(0, -1).split('\n')) {
        const match = /^(Id|LoadState|MainPID)=(.*)$/u.exec(line);
        if (!match || fields.has(match[1])) throw busy();
        fields.set(match[1], match[2]);
      }
      if (fields.size !== 3 || fields.get('Id') !== unit || !['loaded', 'not-found'].includes(fields.get('LoadState') ?? '') ||
          !/^\d+$/u.test(fields.get('MainPID') ?? '') || !Number.isSafeInteger(Number(fields.get('MainPID')))) throw busy();
      const pid = Number(fields.get('MainPID'));
      if (fields.get('LoadState') === 'not-found') { if (pid !== 0) throw busy(); return; }
      if (pid === 0 || pid === context.pid || !pending.some(row => row.pid === pid)) return;
      const restarted = await context.runner('/usr/bin/systemctl', ['--user', 'restart', unit], {env, timeout: 10_000});
      if (restarted.stderr.trim()) throw busy();
    } catch { throw busy(message); }
    return;
  }
  const target = `gui/${context.uid}/${SERVICE}`;
  const message = `The helper could not restart its background service. Run launchctl kickstart -k ${target} in Terminal, then retry the helper command.`;
  let pid: number | undefined;
  try {
    // Bare list emits only PID, exit status and label. A label argument (or print)
    // would collect arguments/environment too. Legacy list uses the caller's
    // bootstrap domain, so verify it is this user's GUI (Aqua) domain first.
    // Root's legacy list targets the system domain even in an Aqua context.
    if (context.uid === 0) throw busy();
    const metadata = async (command: string) => {
      const result = await context.runner('/bin/launchctl', [command], {env: ENV, timeout: 2000});
      if (result.stderr.trim()) throw busy();
      return result.stdout;
    };
    if (await metadata('manageruid') !== `${context.uid}\n` || await metadata('managername') !== 'Aqua\n') throw busy();
    pid = servicePid(await metadata('list'));
  } catch { throw busy(message); }
  // Loaded but not running, or absent in a verified domain, has no old process.
  if (pid === undefined || pid === context.pid || !pending.some(row => row.pid === pid)) return;
  try {
    const result = await context.runner('/bin/launchctl', ['kickstart', '-k', target], {env: ENV, timeout: 10_000});
    if (result.stderr.trim()) throw busy();
  }
  catch { throw busy(message); }
}

export function formatRetirementMessage(pending: readonly ProcessIdentity[], ownPid = process.pid): string {
  const labels = pending.filter(row => row.pid !== ownPid).map(row => {
    const image = [...row.executable].map(value => isControl(value) ? '?' : value).join('');
    const name = posix.basename(image) || 'process';
    return `${name} (PID ${row.pid}) at ${image}`;
  });
  let message = 'The helper lock upgrade is waiting for old processes to finish. Wait for running helper commands, then retry.';
  if (labels.length) message += ` Quit and reopen the listed apps. For running commands, wait for them to finish or close their owning command terminal. Processes: ${labels.join(', ')}.`;
  if (pending.some(row => row.pid === ownPid)) message += ' Let this helper command finish, then retry it in a new process.';
  return message;
}

modules.write-lock:
// maddots-write-lock-protocol: 3
import { spawn } from 'node:child_process';
import { constants } from 'node:fs';
import { lstat, open, unlink, type FileHandle } from 'node:fs/promises';
import { HelperError, clock, type Timing } from './config.js';
import { assertNoSymlinks, ensurePrivateDirectory, readPrivateFile, type HelperPaths } from './paths.js';
import { assertLockUpgradeReady } from './write-lock-upgrade.js';
import { linuxProcessIdentity } from './linux-proc.js';
import { signalIfStillOwned } from './runner/signal-gate.js';

const owner = () => process.getuid?.();
async function processAlive(pid: number): Promise<boolean> {
  if (process.platform === 'linux') return await linuxProcessIdentity(pid) !== null;
  try { return (await signalIfStillOwned({kind: 'probe', pid}, 0)).status === 'sent'; }
  catch { return true; }
}
const lockBusy = () => new HelperError('HELPER_BUSY', 'Another helper command is writing. Try again shortly.');
const sameFile = (a: {dev: number; ino: number}, b: {dev: number; ino: number}) => a.dev === b.dev && a.ino === b.ino;
// Node/libuv also sets close-on-exec, but request it at the Linux open itself.
// Node does not expose Linux's O_CLOEXEC in fs.constants.
const linuxCloseOnExec = 0x80000;
const pendingLinuxUtilities = new Map<string, {file: FileHandle; child: ReturnType<typeof spawn>; settlement: Promise<void>}>();
class RetainedUtilityRefusal extends HelperError {
  constructor() { super('LOCK_UNSAFE', 'The helper could not acquire its Linux kernel write lock. Check that /usr/bin/flock is available, then retry.'); }
}

// flock(1) operates on the inherited open file description, so the parent keeps
// the kernel lock after the short-lived utility exits. Node opens its original
// descriptor close-on-exec; only this explicitly selected child receives FD 3.
function linuxFlock(file: FileHandle, identity: string, remaining: number): Promise<boolean> {
  if (pendingLinuxUtilities.has(identity)) return Promise.reject(lockBusy());
  return new Promise((resolve, reject) => {
    const failed = () => new HelperError('LOCK_UNSAFE', 'The helper could not acquire its Linux kernel write lock. Check that /usr/bin/flock is available, then retry.');
    const child = spawn('/usr/bin/flock', ['--exclusive', '--nonblock', '--conflict-exit-code', '75', '3'], {
      env: {}, stdio: ['ignore', 'ignore', 'ignore', file.fd],
    });
    let settled!: () => void, retained = false;
    const settlement = new Promise<void>(done => {settled = done;});
    const responsibility = {file, child, settlement};
    pendingLinuxUtilities.set(identity, responsibility);
    const refuse = () => {
      if (retained) return;
      retained = true;
      // A timeout ends only this caller's wait. A utility that is delayed before
      // flock may still acquire the inherited open description later. Keep the
      // original FD and child strongly reachable, with no replacement attempt,
      // until close proves that utility can no longer acquire or hold the lock.
      void settlement.then(async () => {
        await file.close();
        if (pendingLinuxUtilities.get(identity) === responsibility) pendingLinuxUtilities.delete(identity);
      }).catch(() => {}); // Failed close retains responsibility and refuses reuse.
      reject(new RetainedUtilityRefusal());
    };
    const timeout = setTimeout(refuse, Math.max(1, Math.min(2000, remaining)));
    child.once('error', () => { clearTimeout(timeout); refuse(); });
    child.once('close', (code, signal) => {
      clearTimeout(timeout);
      settled();
      if (retained) return;
      if (pendingLinuxUtilities.get(identity) === responsibility) pendingLinuxUtilities.delete(identity);
      if (signal || (code !== 0 && code !== 75)) reject(failed());
      else resolve(code === 0);
    });
  });
}

// Call only while holding the guard. Keeping the descriptor open also prevents
// inode reuse before the comparison. The guard makes compare/unlink indivisible
// with respect to other acquisitions, recoveries and releases.
async function removeOwnedLock(path: string, file: FileHandle): Promise<void> {
  const held = await file.stat();
  try { if (sameFile(held, await lstat(path))) await unlink(path); }
  catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error; }
}

export type WriteGuardRelease = (() => Promise<void>) & {assertCurrent(): Promise<void>};
export type DirectoryWriteGuardProgress = 'acquiring' | 'contended';

/** Linux runner exclusion is the directory inode, never a replaceable child name. */
export async function acquireDirectoryWriteGuard(directory: FileHandle, timing: Timing, deadline: number,
  progress?: (state: DirectoryWriteGuardProgress) => void): Promise<WriteGuardRelease> {
  progress?.('acquiring');
  if (process.platform !== 'linux') throw new HelperError('LOCK_UNSAFE', 'Directory write locks require Linux.');
  const retained = await directory.stat();
  if (!retained.isDirectory() || retained.uid !== owner() || (retained.mode & 0o777) !== 0o700) {
    throw new HelperError('LOCK_UNSAFE', 'The runner lock requires a retained private directory.');
  }
  // Open the pinned object, not its public pathname. This independent open
  // description belongs to the lock utility even if acquisition times out and
  // the caller closes its original directory FD. Its inode cannot be recycled
  // while either reference survives, and aliases necessarily flock that inode.
  const file = await open(`/proc/self/fd/${directory.fd}/.`,
    constants.O_RDONLY | constants.O_DIRECTORY | constants.O_NOFOLLOW | linuxCloseOnExec);
  try {
    const info = await file.stat();
    if (!info.isDirectory() || !sameFile(retained, info) || info.uid !== owner() || (info.mode & 0o777) !== 0o700) {
      throw new HelperError('LOCK_UNSAFE', 'The runner lock directory was replaced.');
    }
    while (true) {
      if (timing.now() >= deadline) throw lockBusy();
      progress?.('acquiring');
      if (await linuxFlock(file, `${info.dev}:${info.ino}`, deadline - timing.now())) break;
      // Only a completed nonblocking flock conflict certifies contention.
      // Directory preparation or an outstanding utility remains unresolved.
      progress?.('contended');
      if (timing.now() >= deadline) throw lockBusy();
      await timing.sleep(50);
    }
    let released: Promise<void> | undefined;
    return Object.assign(() => released ??= file.close(), {assertCurrent: async () => {
      // The storage owner validates the retained directory's metadata and
      // namespace. No child pathname can change this kernel lock's identity.
      if (released) throw new HelperError('LOCK_UNSAFE', 'The runner directory lock was released.');
    }});
  } catch (error) {
    // linuxFlock retains its own directory FD until the utility's real close.
    if (!(error instanceof RetainedUtilityRefusal)) await file.close();
    throw error;
  }
}

export async function acquireWriteGuard(path: string, timing: Timing, deadline: number,
  retainedDirectory?: FileHandle): Promise<WriteGuardRelease> {
  // Darwin's <sys/fcntl.h> defines O_EXLOCK as 0x20; Node does not export it.
  // The kernel releases this flock on close/crash. NEVER unlink its stable inode:
  // replacing it would let two processes lock different inodes for the same path.
  const kernelLock = process.platform === 'darwin' || process.platform === 'linux';
  const flags = constants.O_RDWR | constants.O_CREAT | constants.O_NOFOLLOW | constants.O_NONBLOCK |
    (process.platform === 'darwin' ? 0x20 : process.platform === 'linux' ? linuxCloseOnExec : constants.O_EXCL);
  while (true) {
    if (timing.now() >= deadline) throw lockBusy();
    if (retainedDirectory) {
      // Only the runner's Linux controller may supply this capability. The
      // procfs prefix is fixed by its live descriptor, with one local basename;
      // O_NOFOLLOW below still refuses a symlink at that basename.
      const prefix = `/proc/self/fd/${retainedDirectory.fd}/`, name = path.slice(prefix.length);
      const info = await retainedDirectory.stat();
      if (process.platform !== 'linux' || !path.startsWith(prefix) || !/^[A-Za-z0-9._-]+$/u.test(name) ||
          name === '.' || name === '..' || !info.isDirectory() || info.uid !== owner() || (info.mode & 0o777) !== 0o700) {
        throw new HelperError('LOCK_UNSAFE', 'The helper lock guard requires a retained private directory.');
      }
    } else await assertNoSymlinks(path);
    let guard: FileHandle;
    try { guard = await open(path, flags, 0o600); }
    catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      if (kernelLock ? code !== 'EAGAIN' && code !== 'EWOULDBLOCK' : code !== 'EEXIST') throw error;
      // Unsupported platforms use O_EXCL and deliberately never reclaim an
      // abandoned guard. PID/age checks would just repeat the stale-unlink race.
      if (timing.now() >= deadline) throw lockBusy();
      await timing.sleep(50); continue;
    }
    let retainedIdentity!: {dev: number; ino: number};
    try {
      const info = await guard.stat();
      if (!info.isFile() || info.uid !== owner() || (info.mode & 0o777) !== 0o600 || info.nlink !== 1) {
        throw new HelperError('LOCK_UNSAFE', 'The helper lock guard must be a private, owned, regular file with one link.');
      }
      if (!sameFile(info, await lstat(path))) throw new HelperError('LOCK_UNSAFE', 'The helper lock guard was replaced.');
      if (process.platform === 'linux') {
        if (!await linuxFlock(guard, `${info.dev}:${info.ino}`, deadline - timing.now())) {
          await guard.close();
          if (timing.now() >= deadline) throw lockBusy();
          await timing.sleep(50); continue;
        }
        if (!sameFile(info, await lstat(path))) throw new HelperError('LOCK_UNSAFE', 'The helper lock guard was replaced.');
      }
      if (!kernelLock) { await guard.writeFile(String(process.pid)); await guard.sync(); }
      retainedIdentity = {dev: info.dev, ino: info.ino};
    } catch (error) {
      if (error instanceof RetainedUtilityRefusal) throw error;
      try { if (!kernelLock) await removeOwnedLock(path, guard); }
      finally { await guard.close(); }
      throw error;
    }
    let released = false;
    const release = async () => {
      released = true;
      try { if (!kernelLock) await removeOwnedLock(path, guard); }
      finally { await guard.close(); }
    };
    return Object.assign(release, {assertCurrent: async () => {
      if (retainedDirectory && released) throw new HelperError('LOCK_UNSAFE', 'The helper lock guard was released.');
      const descriptor = retainedDirectory ? undefined : await guard.stat();
      const current = await lstat(path);
      // A matching name beneath the retained directory is the locked inode:
      // guard stays open until release, so its identity cannot be recycled.
      // Avoid a second metadata read of that same inode for bound Linux guards.
      const held = descriptor ?? current;
      if (!held.isFile() || !current.isFile() || !sameFile(retainedIdentity, held) || !sameFile(retainedIdentity, current) ||
          held.nlink !== 1 || current.nlink !== 1 || held.uid !== owner() || current.uid !== owner() ||
          (held.mode & 0o777) !== 0o600 || (current.mode & 0o777) !== 0o600) {
        throw new HelperError('LOCK_UNSAFE', 'The helper lock guard was replaced.');
      }
    }});
  }
}

export async function withWriteLock<T>(paths: HelperPaths, action: (release: () => Promise<void>) => Promise<T>, timing: Timing = clock,
  alive: (pid: number) => boolean | Promise<boolean> = processAlive, deadline = timing.now() + 10_000): Promise<T> {
  await assertLockUpgradeReady(paths, timing);
  await ensurePrivateDirectory(paths.data);
  const unlockGuard = await acquireWriteGuard(paths.lock + '.guard', timing, deadline);
  let file: FileHandle | undefined;
  let released: Promise<void> | undefined;
  const release = () => released ??= (async () => {
    try { if (file) await removeOwnedLock(paths.lock, file); }
    finally { try { await file?.close(); } finally { await unlockGuard(); } }
  })();
  try {
    while (!file) {
      if (timing.now() >= deadline) throw lockBusy();
      await assertNoSymlinks(paths.lock);
      try { file = await open(paths.lock, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | constants.O_NOFOLLOW, 0o600); }
      catch (error) {
        if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error;
        try {
          const previous = await lstat(paths.lock);
          const text = await readPrivateFile(paths.lock, 32);
          if (!text && timing.now() < deadline) { await timing.sleep(50); continue; }
          const pid = Number(text);
          if (!/^\d+$/.test(text) || !Number.isSafeInteger(pid) || pid <= 0) throw new HelperError('LOCK_UNSAFE', 'The helper lock is invalid. Inspect the private .lock file before reconnecting.');
          if (!await alive(pid)) {
            const latest = await lstat(paths.lock);
            if (sameFile(previous, latest)) await unlink(paths.lock);
            continue;
          }
        } catch (inspection) { if ((inspection as NodeJS.ErrnoException).code === 'ENOENT') continue; throw inspection; }
        if (timing.now() >= deadline) throw lockBusy();
        await timing.sleep(50);
      }
    }
    await file.writeFile(String(process.pid)); await file.sync(); return await action(release);
  }
  finally { await release(); }
}
